CREATE TABLE IF NOT EXISTS records (
    customer_id TEXT,
    age INTEGER,
    occupation TEXT,
    annual_income INTEGER,
    total_debt INTEGER,
    debt_to_income REAL,
    credit_utilization REAL,
    num_late_payments INTEGER,
    loan_purpose TEXT,
    credit_score INTEGER,
    default_probability REAL,
    defaulted INTEGER,
    recorded_at TEXT
);

